```java
class Counter {
    int field = 0;
    void demo() {
        int local = 0;
        Runnable r1 = () -> System.out.println(local);  // чтение OK
        // local++;  // сделало бы local не effectively final -> ошибка

        Runnable r2 = () -> field++;   // мутация поля через this — OK, но не thread-safe
        r2.run();

        int[] holder = {0};            // массив — effectively final ссылка
        Runnable r3 = () -> holder[0]++;  // workaround для mutable-«локального»

        AtomicInteger atomic = new AtomicInteger(0);  // thread-safe вариант
        Runnable r4 = () -> atomic.incrementAndGet();
    }
}
```

