Кастомный throwing-интерфейс + адаптер:
```java
@FunctionalInterface
interface ThrowingFunction<T, R, E extends Exception> {
    R apply(T t) throws E;
    default Function<T, R> unchecked() {
        return t -> { try { return apply(t); }
                      catch (Exception e) { throw new RuntimeException(e); } };
    }
}
Function<String, byte[]> wrapped =
    ((ThrowingFunction<String, byte[], IOException>) Files::readAllBytes).unchecked();
```

```java
@FunctionalInterface
public interface Validator<T> {
    ValidationResult validate(T value);   // детализированный результат, не boolean

    default Validator<T> and(Validator<T> other) {
        return value -> {
            ValidationResult r1 = this.validate(value);
            return r1.isValid() ? other.validate(value) : r1;
        };
    }
    default Validator<T> withMessage(String msg) {
        return value -> {
            ValidationResult r = this.validate(value);
            return r.isValid() ? r : ValidationResult.fail(msg);
        };
    }
}

// Checked exceptions — невозможно через стандартный Function:
@FunctionalInterface
public interface RestCallback<T> {
    T call(HttpRequest req) throws IOException, HttpException;
}
